import type { AnimationGroup, AnimationGroupMask } from "@babylonjs/lite";

export function restoreMask(group: AnimationGroup, saved: AnimationGroupMask): void {
    group.mask = {
        mode: saved.mode,
        names: [...saved.names],
        disabled: saved.disabled,
    };
}
```

I created `src/restore-mask.ts` with a `restoreMask` function that assigns a fresh mask object (with a copied `names` array) to `group.mask`, which is all the library needs to apply the mask on subsequent updates. I'm not sure of anything—the type declarations and notes (especially #38 and #40) make the behavior clear: the library reads `group.mask` each tick, masked-out nodes get rest values written, and a new object/array reference is what makes the change visible.
